            connection.execute(
                "SELECT path, size, mtime_ns FROM shards ORDER BY shard_id"
            )
        )
        rows = connection.execute(
            """
            SELECT shard_id, offset, size, speaker_label
            FROM samples
            ORDER BY sample_id
            """
        ).fetchall()
    finally:
        connection.close()

    for path, expected_size, expected_mtime_ns in shards:
